public int lastOddValue() {
    for (int i = arrayNum.length - 1; i >= 0; i--) {
        if (arrayNum[i] % 2 != 0) {
            return arrayNum[i];
        }
    }
    return -1;   // לא יקרה: הנחנו שיש במערך מספר אי-זוגי
}

